  :: forall m
   . (MonadIO m)
  => CommandBuffer
  -> StencilFaceFlags
  -> Word32
  -> m ()
cmdSetStencilCompareMask commandBuffer faceMask compareMask =
  liftIO do
    liftIO
      ( mkCmdSetStencilCompareMask
          (checkCommandPtr "vkCmdSetStencilCompareMask" commandBuffer.cmds.pCmdSetStencilCompareMask)
          (castPtr commandBuffer.handle)
          ((\(Flags w) -> w) faceMask)
          compareMask
      )
    pure ()

