-- | Registry: <https://registry.khronos.org/vulkan/specs/latest/man/html/vkCmdSetViewport.html vkCmdSetViewport>
-- Available: VK_VERSION_1_0
cmdSetViewport
  :: forall m
   . (MonadIO m)
  => CommandBuffer
  -> Word32
  -> V.Vector Viewport
  -> m ()
cmdSetViewport commandBuffer firstViewport viewports =
  liftIO $ withArena \arena_ -> runAlloc arena_ do
    let n_viewportCount = fromIntegral (V.length viewports) :: Word32
    p_viewports <- do pv_ <- newVector viewports; pure (castPtr pv_ :: Ptr ())
    liftIO
      ( mkCmdSetViewport
          (checkCommandPtr "vkCmdSetViewport" commandBuffer.cmds.pCmdSetViewport)
          (castPtr commandBuffer.handle)
          firstViewport
          n_viewportCount
          p_viewports
      )
    pure ()

-- | Registry: <https://registry.khronos.org/vulkan/specs/latest/man/html/vkCmdUpdateBuffer.html vkCmdUpdateBuffer>
-- Available: VK_VERSION_1_0
-- __Deprecated__: superseded by vkCmdUpdateMemoryKHR.
cmdUpdateBuffer
  :: forall m
   . (MonadIO m)
  => CommandBuffer
  -> Buffer
  -> DeviceSize
  -> ByteString
  -> m ()
cmdUpdateBuffer commandBuffer dstBuffer dstOffset data' =
  liftIO $ withArena \arena_ -> runAlloc arena_ do
    let n_dataSize = fromIntegral (BS.length data') :: Word64
    p_data' :: Ptr () <- castPtr <$> newBytes data'
    liftIO
      ( mkCmdUpdateBuffer
          (checkCommandPtr "vkCmdUpdateBuffer" commandBuffer.cmds.pCmdUpdateBuffer)
          (castPtr commandBuffer.handle)
          (case dstBuffer of Buffer w_ -> w_)
          (fromIntegral dstOffset :: Word64)
          n_dataSize
          p_data'
      )
    pure ()
